20	namespace
21	{
22	
23	alignas(16) uint8_t g_tensor_arena[CONFIG_EXAMPLES_AUDIO_EVENT_ARENA_SIZE];
24	
25	tflite::MicroInterpreter *g_interpreter;
26	TfLiteTensor *g_input;
27	TfLiteTensor *g_output;
28	size_t g_arena_used;
29	
30	int tensor_element_count(const TfLiteTensor *tensor)
31	{
32	  int count = 1;
33	
34	  if (tensor == nullptr || tensor->dims == nullptr)
35	    {
36	      return 0;
37	    }
38	
39	  for (int i = 0; i < tensor->dims->size; i++)
40	    {
41	      count *= tensor->dims->data[i];
42	    }
43	
44	  return count;
45	}
46	
47	int read_output(float *probabilities, size_t class_count)
48	{
49	  if (g_output == nullptr || probabilities == nullptr ||
50	      class_count != AUDIO_EVENT_CLASS_COUNT)
51	    {
52	      return -EINVAL;
53	    }
54	
55	  for (size_t i = 0; i < class_count; i++)
56	    {
57	      probabilities[i] =
58	          (static_cast<int>(g_output->data.int8[i]) -
59	           g_output->params.zero_point) *
60	          g_output->params.scale;
61	    }
62	
63	  return 0;
64	}
65	
66	}  // namespace
67	
68	extern "C" int event_classifier_init(void)
69	{
70	  static tflite::MicroMutableOpResolver<9> resolver;
71	  static bool resolver_initialized;
72	
73	  const tflite::Model *model = tflite::GetModel(g_audio_event_model);
74	  if (model == nullptr || model->version() != TFLITE_SCHEMA_VERSION)
75	    {
76	      std::fprintf(stderr, "[model] schema mismatch: model=%d runtime=%d\n",
77	                   model == nullptr ? -1 : model->version(),
78	                   TFLITE_SCHEMA_VERSION);
79	      return -EINVAL;
80	    }
81	
82	  if (!resolver_initialized)
83	    {
84	      if (resolver.AddShape() != kTfLiteOk ||
85	          resolver.AddStridedSlice() != kTfLiteOk ||
86	          resolver.AddPack() != kTfLiteOk ||
87	          resolver.AddReshape() != kTfLiteOk ||
88	          resolver.AddConv2D() != kTfLiteOk ||
89	          resolver.AddDepthwiseConv2D() != kTfLiteOk ||
90	          resolver.AddMean() != kTfLiteOk ||
91	          resolver.AddFullyConnected() != kTfLiteOk ||
92	          resolver.AddSoftmax() != kTfLiteOk)
93	        {
94	          std::fprintf(stderr, "[model] failed to register operators\n");
95	          return -EINVAL;
96	        }
97	
98	      resolver_initialized = true;
99	    }
100	
101	  static tflite::MicroInterpreter interpreter(
102	      model, resolver, g_tensor_arena, sizeof(g_tensor_arena));
103	
104	  if (interpreter.AllocateTensors() != kTfLiteOk)
105	    {
106	      std::fprintf(stderr, "[model] AllocateTensors failed, arena=%zu\n",
107	                   sizeof(g_tensor_arena));
108	      return -ENOMEM;
109	    }
110	
111	  g_interpreter = &interpreter;
112	  g_input = interpreter.input(0);
113	  g_output = interpreter.output(0);
114	  g_arena_used = interpreter.arena_used_bytes();
115	
116	  if (g_input == nullptr || g_input->type != kTfLiteInt8 ||
117	      tensor_element_count(g_input) != AUDIO_EVENT_FEATURE_SIZE)
118	    {
119	      std::fprintf(stderr,
120	                   "[model] expected int8 input with %d elements, "
121	                   "got type=%d\n",
122	                   AUDIO_EVENT_FEATURE_SIZE,
123	                   g_input == nullptr ? -1 : static_cast<int>(g_input->type));
124	      event_classifier_deinit();
125	      return -EINVAL;
126	    }
127	
128	  if (g_output == nullptr || g_output->type != kTfLiteInt8 ||
129	      tensor_element_count(g_output) != AUDIO_EVENT_CLASS_COUNT)
130	    {
131	      std::fprintf(stderr,
132	                   "[model] expected int8 output with %d elements, "
133	                   "got type=%d\n",
134	                   AUDIO_EVENT_CLASS_COUNT,
135	                   g_output == nullptr ? -1 :
136	                                         static_cast<int>(g_output->type));
137	      event_classifier_deinit();
138	      return -EINVAL;
139	    }
140	
141	  std::printf("[model] arena=%lu used=%lu model=%u bytes\n",
142	              static_cast<unsigned long>(sizeof(g_tensor_arena)),
143	              static_cast<unsigned long>(g_arena_used),
144	              g_audio_event_model_len);
145	  return 0;
146	}
147	
148	extern "C" void event_classifier_deinit(void)
149	{
150	  g_interpreter = nullptr;
151	  g_input = nullptr;
152	  g_output = nullptr;
153	  g_arena_used = 0;
154	}
155	
156	extern "C" int event_classifier_predict_quantized(
157	    const int8_t *features, size_t feature_count, float *probabilities,
158	    size_t class_count)
159	{
160	  if (g_interpreter == nullptr || g_input == nullptr || features == nullptr ||
161	      feature_count != AUDIO_EVENT_FEATURE_SIZE ||
162	      class_count != AUDIO_EVENT_CLASS_COUNT)
163	    {
164	      return -EINVAL;
165	    }
166	
167	  std::memcpy(g_input->data.int8, features, feature_count);
168	  if (g_interpreter->Invoke() != kTfLiteOk)
169	    {
170	      std::fprintf(stderr, "[model] Invoke failed\n");
171	      return -EIO;
172	    }
173	
174	  return read_output(probabilities, class_count);
175	}
176	
177	extern "C" int event_classifier_predict(const float *features,
178	                                        size_t feature_count,
179	                                        float *probabilities,
180	                                        size_t class_count)
181	{
182	  if (g_interpreter == nullptr || g_input == nullptr || features == nullptr ||
183	      feature_count != AUDIO_EVENT_FEATURE_SIZE ||
184	      class_count != AUDIO_EVENT_CLASS_COUNT ||
185	      g_input->params.scale <= 0.0f)
186	    {
187	      return -EINVAL;
188	    }
189	
190	  for (size_t i = 0; i < feature_count; i++)
191	    {
192	      long value = std::lround(features[i] / g_input->params.scale) +
193	                   g_input->params.zero_point;
194	      if (value < -128)
195	        {
196	          value = -128;
197	        }
198	      else if (value > 127)
199	        {
200	          value = 127;
201	        }
202	
203	      g_input->data.int8[i] = static_cast<int8_t>(value);
204	    }
205	
206	  if (g_interpreter->Invoke() != kTfLiteOk)
207	    {
208	      std::fprintf(stderr, "[model] Invoke failed\n");
209	      return -EIO;
210	    }
211	
212	  return read_output(probabilities, class_count);
213	}
214	
215	extern "C" size_t event_classifier_arena_used(void)
216	{
217	  return g_arena_used;
218	}
