1	/*
2	 * Audio event detection application entry point.
3	 */
4	
5	#include <nuttx/config.h>
6	
7	#include <errno.h>
8	#include <stdbool.h>
9	#include <stdint.h>
10	#include <stdio.h>
11	#include <stdlib.h>
12	#include <string.h>
13	
14	#include "alert/event_alert.h"
15	#include "audio/audio_capture.h"
16	#include "audio/audio_file.h"
17	#include "audio_event_config.h"
18	#include "detector/event_detector.h"
19	#include "dsp/feature_extract.h"
20	#include "model/event_classifier.h"
21	
22	#define AUDIO_IO_BLOCK_SAMPLES 512
23	
24	enum input_mode_e
25	{
26	  INPUT_MODE_DEVICE = 0,
27	  INPUT_MODE_FILE
28	};
29	
30	struct app_options_s
31	{
32	  enum input_mode_e mode;
33	  const char *path;
34	  unsigned int repeat_count;
35	  bool once;
36	  bool model_smoke;
37	};
38	
39	static const char *const g_event_names[AUDIO_EVENT_CLASS_COUNT] =
40	{
41	  "knock",
42	  "cough",
43	  "background",
44	  "silence"
45	};
46	
47	static int16_t g_audio_ring[AUDIO_EVENT_CLIP_SAMPLES];
48	static int16_t g_audio_window[AUDIO_EVENT_CLIP_SAMPLES];
49	static int16_t g_audio_block[AUDIO_IO_BLOCK_SAMPLES];
50	static float g_features[AUDIO_EVENT_FEATURE_SIZE];
51	static float g_probabilities[AUDIO_EVENT_CLASS_COUNT];
52	
53	static void usage(const char *program)
54	{
55	  printf("Usage: %s [--file PATH | --device PATH] [--once] "
56	         "[--repeat N] [--model-smoke]\n", program);
57	  printf("  --file PATH    Read 16 kHz mono PCM16 or WAV from HostFS\n");
58	  printf("  --device PATH  Read from a NuttX Audio capture device\n");
59	  printf("  --once         Stop after the first one-second inference\n");
60	  printf("  --repeat N     Repeat file input N times (default: 1)\n");
61	  printf("  --model-smoke  Invoke the model with silence features\n");
62	}
63	
64	static int parse_options(int argc, char **argv, struct app_options_s *options)
65	{
66	  int i;
67	
68	  options->mode = INPUT_MODE_DEVICE;
69	  options->path = CONFIG_EXAMPLES_AUDIO_EVENT_DEVPATH;
70	  options->repeat_count = 1;
71	  options->once = false;
72	  options->model_smoke = false;
73	
74	  for (i = 1; i < argc; i++)
75	    {
76	      if (strcmp(argv[i], "--file") == 0 && i + 1 < argc)
77	        {
78	          options->mode = INPUT_MODE_FILE;
79	          options->path = argv[++i];
80	        }
81	      else if (strcmp(argv[i], "--device") == 0 && i + 1 < argc)
82	        {
83	          options->mode = INPUT_MODE_DEVICE;
84	          options->path = argv[++i];
85	        }
86	      else if (strcmp(argv[i], "--once") == 0)
87	        {
88	          options->once = true;
89	        }
90	      else if (strcmp(argv[i], "--repeat") == 0 && i + 1 < argc)
91	        {
92	          char *end;
93	          unsigned long repeat = strtoul(argv[++i], &end, 10);
94	          if (*end != '\0' || repeat == 0 || repeat > UINT16_MAX)
95	            {
96	              return -EINVAL;
97	            }
98	
99	          options->repeat_count = (unsigned int)repeat;
100	        }
101	      else if (strcmp(argv[i], "--model-smoke") == 0)
102	        {
103	          options->model_smoke = true;
104	        }
105	      else if (strcmp(argv[i], "--help") == 0 ||
106	               strcmp(argv[i], "-h") == 0)
107	        {
108	          usage(argv[0]);
109	          return 1;
110	        }
111	      else
112	        {
113	          fprintf(stderr, "Unknown or incomplete option: %s\n", argv[i]);
114	          usage(argv[0]);
115	          return -EINVAL;
116	        }
117	    }
118	
119	  return 0;
120	}
121	
122	static int best_class(const float *probabilities)
123	{
124	  int best = 0;
125	  int i;
126	
127	  for (i = 1; i < AUDIO_EVENT_CLASS_COUNT; i++)
128	    {
129	      if (probabilities[i] > probabilities[best])
130	        {
131	          best = i;
132	        }
133	    }
134	
135	  return best;
136	}
137	
138	static int probability_permille(float probability)
139	{
140	  int value = (int)(probability * 1000.0f + 0.5f);
141	
142	  if (value < 0)
143	    {
144	      value = 0;
145	    }
146	  else if (value > 1000)
147	    {
148	      value = 1000;
149	    }
150	
151	  return value;
152	}
153	
154	static void print_probabilities(uint64_t timestamp_ms)
155	{
156	  int best = best_class(g_probabilities);
157	
158	  printf("[infer] t=%llu ms class=%s probs_permille=[%d %d %d %d]\n",
159	         (unsigned long long)timestamp_ms, g_event_names[best],
160	         probability_permille(g_probabilities[0]),
161	         probability_permille(g_probabilities[1]),
162	         probability_permille(g_probabilities[2]),
163	         probability_permille(g_probabilities[3]));
164	}
165	
166	static int run_model_smoke(void)
167	{
168	  int ret;
169	
170	  memset(g_features, 0, sizeof(g_features));
171	  ret = event_classifier_predict(g_features, AUDIO_EVENT_FEATURE_SIZE,
172	                                 g_probabilities,
173	                                 AUDIO_EVENT_CLASS_COUNT);
174	  if (ret < 0)
175	    {
176	      return ret;
177	    }
178	
179	  print_probabilities(0);
180	  return 0;
181	}
182	
183	static void ring_append(size_t *write_position, const int16_t *samples,
184	                        size_t sample_count)
185	{
186	  size_t i;
187	
188	  for (i = 0; i < sample_count; i++)
189	    {
190	      g_audio_ring[*write_position] = samples[i];
191	      *write_position = (*write_position + 1) % AUDIO_EVENT_CLIP_SAMPLES;
192	    }
193	}
194	
195	static void ring_copy_window(size_t write_position)
196	{
197	  size_t tail = AUDIO_EVENT_CLIP_SAMPLES - write_position;
198	
199	  memcpy(g_audio_window, &g_audio_ring[write_position],
200	         tail * sizeof(int16_t));
201	  if (write_position > 0)
202	    {
203	      memcpy(&g_audio_window[tail], g_audio_ring,
204	             write_position * sizeof(int16_t));
205	    }
206	}
207	
208	static int process_window(size_t write_position, uint64_t timestamp_ms)
209	{
210	  struct event_detection_s detection;
211	  int ret;
212	
213	  ring_copy_window(write_position);
214	  ret = feature_extract_compute(g_audio_window, AUDIO_EVENT_CLIP_SAMPLES,
215	                                g_features, AUDIO_EVENT_FEATURE_SIZE);
216	  if (ret < 0)
217	    {
218	      fprintf(stderr, "[feature] compute failed: %d\n", ret);
219	      return ret;
220	    }
221	
222	  ret = event_classifier_predict(g_features, AUDIO_EVENT_FEATURE_SIZE,
223	                                 g_probabilities,
224	                                 AUDIO_EVENT_CLASS_COUNT);
225	  if (ret < 0)
226	    {
227	      fprintf(stderr, "[model] prediction failed: %d\n", ret);
228	      return ret;
229	    }
230	
231	  print_probabilities(timestamp_ms);
232	  ret = event_detector_update(g_probabilities, AUDIO_EVENT_CLASS_COUNT,
233	                              timestamp_ms, &detection);
234	  if (ret < 0)
235	    {
236	      return ret;
237	    }
238	
239	  if (detection.fired)
240	    {
241	      event_alert_fire(detection.class_id,
242	                       g_event_names[detection.class_id],
243	                       detection.confidence);
244	    }
245	
246	  return 0;
247	}
