249	int audio_event_main(int argc, char *argv[])
250	{
251	  struct app_options_s options;
252	  struct audio_file_s file_source;
253	  size_t write_position = 0;
254	  size_t samples_until_inference = AUDIO_EVENT_CLIP_SAMPLES;
255	  uint64_t total_samples = 0;
256	  unsigned int windows = 0;
257	  bool file_open = false;
258	  bool capture_open = false;
259	  int ret;
260	
261	  memset(&file_source, 0, sizeof(file_source));
262	  file_source.fd = -1;
263	
264	  ret = parse_options(argc, argv, &options);
265	  if (ret != 0)
266	    {
267	      return ret > 0 ? 0 : EXIT_FAILURE;
268	    }
269	
270	  printf("=== Audio Event Detection ===\n");
271	  ret = event_classifier_init();
272	  if (ret < 0)
273	    {
274	      return EXIT_FAILURE;
275	    }
276	
277	  if (options.model_smoke)
278	    {
279	      ret = run_model_smoke();
280	      event_classifier_deinit();
281	      return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
282	    }
283	
284	  ret = feature_extract_init();
285	  if (ret < 0)
286	    {
287	      event_classifier_deinit();
288	      return EXIT_FAILURE;
289	    }
290	
291	  event_detector_init();
292	  ret = event_alert_init();
293	  if (ret < 0)
294	    {
295	      fprintf(stderr, "[alert] init failed: %d, serial output remains\n", ret);
296	    }
297	
298	  if (options.mode == INPUT_MODE_FILE)
299	    {
300	      ret = audio_file_open(&file_source, options.path,
301	                            options.repeat_count);
302	      file_open = ret == 0;
303	    }
304	  else
305	    {
306	      ret = audio_capture_init(options.path);
307	      capture_open = ret == 0;
308	    }
309	
310	  if (ret < 0)
311	    {
312	      goto cleanup;
313	    }
314	
315	  printf("[app] source=%s hop=%d ms\n",
316	         options.mode == INPUT_MODE_FILE ? "file" : "device",
317	         CONFIG_EXAMPLES_AUDIO_EVENT_HOP_MS);
318	
319	  for (;;)
320	    {
321	      size_t request = samples_until_inference;
322	      ssize_t count;
323	
324	      if (request > AUDIO_IO_BLOCK_SAMPLES)
325	        {
326	          request = AUDIO_IO_BLOCK_SAMPLES;
327	        }
328	
329	      if (options.mode == INPUT_MODE_FILE)
330	        {
331	          count = audio_file_read(&file_source, g_audio_block, request);
332	        }
333	      else
334	        {
335	          count = audio_capture_read(g_audio_block, request);
336	        }
337	
338	      if (count < 0)
339	        {
340	          ret = (int)count;
341	          fprintf(stderr, "[app] audio read failed: %d\n", ret);
342	          break;
343	        }
344	
345	      if (count == 0)
346	        {
347	          ret = windows > 0 ? 0 : -ENODATA;
348	          if (ret < 0)
349	            {
350	              fprintf(stderr, "[app] input ended before one full window\n");
351	            }
352	
353	          break;
354	        }
355	
356	      ring_append(&write_position, g_audio_block, count);
357	      total_samples += count;
358	      samples_until_inference -= count;
359	
360	      if (samples_until_inference == 0)
361	        {
362	          uint64_t timestamp_ms = total_samples * 1000 /
363	                                  AUDIO_EVENT_SAMPLE_RATE;
364	          ret = process_window(write_position, timestamp_ms);
365	          if (ret < 0)
366	            {
367	              break;
368	            }
369	
370	          windows++;
371	          if (options.once)
372	            {
373	              ret = 0;
374	              break;
375	            }
376	
377	          samples_until_inference =
378	              AUDIO_EVENT_SAMPLE_RATE *
379	              CONFIG_EXAMPLES_AUDIO_EVENT_HOP_MS / 1000;
380	          if (samples_until_inference == 0 ||
381	              samples_until_inference > AUDIO_EVENT_CLIP_SAMPLES)
382	            {
383	              fprintf(stderr, "[app] invalid hop configuration\n");
384	              ret = -EINVAL;
385	              break;
386	            }
387	        }
388	    }
389	
390	cleanup:
391	  if (file_open)
392	    {
393	      audio_file_close(&file_source);
394	    }
395	
396	  if (capture_open)
397	    {
398	      audio_capture_deinit();
399	    }
400	
401	  event_alert_deinit();
402	  feature_extract_deinit();
403	  event_classifier_deinit();
404	  printf("[app] stopped, windows=%u status=%d\n", windows, ret);
405	  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
406	}
