1	/*
2	 * Blocking PCM reader built on the asynchronous NuttX Audio API.
3	 */
4	
5	#include <nuttx/config.h>
6	
7	#include <errno.h>
8	#include <fcntl.h>
9	#include <mqueue.h>
10	#include <stdbool.h>
11	#include <stdint.h>
12	#include <stdio.h>
13	#include <string.h>
14	#include <sys/ioctl.h>
15	#include <unistd.h>
16	
17	#include <nuttx/audio/audio.h>
18	
19	#include "audio/audio_capture.h"
20	#include "audio_event_config.h"
21	
22	#define AUDIO_CAPTURE_MAX_BUFFERS 8
23	
24	static int g_audio_fd = -1;
25	static mqd_t g_audio_mq = (mqd_t)-1;
26	static char g_audio_mqname[32];
27	static struct ap_buffer_s *g_audio_buffers[AUDIO_CAPTURE_MAX_BUFFERS];
28	static unsigned int g_audio_buffer_count;
29	static struct ap_buffer_s *g_current_buffer;
30	static size_t g_current_offset;
31	static bool g_audio_started;
32	
33	#ifdef CONFIG_AUDIO_MULTI_SESSION
34	static void *g_audio_session;
35	#endif
36	
37	static int enqueue_buffer(struct ap_buffer_s *buffer)
38	{
39	  struct audio_buf_desc_s descriptor;
40	
41	  buffer->curbyte = 0;
42	  buffer->nbytes = buffer->nmaxbytes;
43	  buffer->flags = 0;
44	  memset(&descriptor, 0, sizeof(descriptor));
45	#ifdef CONFIG_AUDIO_MULTI_SESSION
46	  descriptor.session = g_audio_session;
47	#endif
48	  descriptor.numbytes = buffer->nbytes;
49	  descriptor.u.buffer = buffer;
50	
51	  if (ioctl(g_audio_fd, AUDIOIOC_ENQUEUEBUFFER,
52	            (unsigned long)(uintptr_t)&descriptor) < 0)
53	    {
54	      return -errno;
55	    }
56	
57	  return 0;
58	}
59	
60	static int wait_for_buffer(void)
61	{
62	  struct audio_msg_s message;
63	  unsigned int priority;
64	
65	  for (;;)
66	    {
67	      ssize_t size = mq_receive(g_audio_mq, (char *)&message,
68	                                sizeof(message), &priority);
69	      if (size < 0)
70	        {
71	          if (errno == EINTR)
72	            {
73	              continue;
74	            }
75	
76	          return -errno;
77	        }
78	
79	      if (size != sizeof(message))
80	        {
81	          continue;
82	        }
83	
84	      if (message.msg_id == AUDIO_MSG_DEQUEUE)
85	        {
86	          g_current_buffer = message.u.ptr;
87	          g_current_offset = 0;
88	          return 0;
89	        }
90	
91	      if (message.msg_id == AUDIO_MSG_COMPLETE ||
92	          message.msg_id == AUDIO_MSG_STOP)
93	        {
94	          return -EPIPE;
95	        }
96	    }
97	}
