99	int audio_capture_init(const char *device_path)
100	{
101	  struct audio_caps_desc_s capabilities;
102	  struct ap_buffer_info_s buffer_info;
103	  struct mq_attr attributes;
104	  unsigned int i;
105	  int ret;
106	
107	  if (device_path == NULL || g_audio_fd >= 0)
108	    {
109	      return -EINVAL;
110	    }
111	
112	  g_audio_fd = open(device_path, O_RDWR | O_CLOEXEC);
113	  if (g_audio_fd < 0)
114	    {
115	      ret = -errno;
116	      fprintf(stderr, "[audio] cannot open %s: %d\n", device_path, ret);
117	      return ret;
118	    }
119	
120	#ifdef CONFIG_AUDIO_MULTI_SESSION
121	  ret = ioctl(g_audio_fd, AUDIOIOC_RESERVE,
122	              (unsigned long)(uintptr_t)&g_audio_session);
123	#else
124	  ret = ioctl(g_audio_fd, AUDIOIOC_RESERVE, 0);
125	#endif
126	  if (ret < 0)
127	    {
128	      ret = -errno;
129	      goto fail;
130	    }
131	
132	  memset(&capabilities, 0, sizeof(capabilities));
133	#ifdef CONFIG_AUDIO_MULTI_SESSION
134	  capabilities.session = g_audio_session;
135	#endif
136	  capabilities.caps.ac_len = sizeof(struct audio_caps_s);
137	  capabilities.caps.ac_type = AUDIO_TYPE_INPUT;
138	  capabilities.caps.ac_subtype = AUDIO_FMT_PCM;
139	  capabilities.caps.ac_channels = 1;
140	  capabilities.caps.ac_controls.hw[0] = AUDIO_EVENT_SAMPLE_RATE;
141	  capabilities.caps.ac_controls.b[3] = AUDIO_EVENT_SAMPLE_RATE >> 16;
142	  capabilities.caps.ac_controls.b[2] = 16;
143	
144	  if (ioctl(g_audio_fd, AUDIOIOC_CONFIGURE,
145	            (unsigned long)(uintptr_t)&capabilities) < 0)
146	    {
147	      ret = -errno;
148	      goto fail;
149	    }
150	
151	  memset(&buffer_info, 0, sizeof(buffer_info));
152	  if (ioctl(g_audio_fd, AUDIOIOC_GETBUFFERINFO,
153	            (unsigned long)(uintptr_t)&buffer_info) < 0)
154	    {
155	      buffer_info.nbuffers = CONFIG_AUDIO_NUM_BUFFERS;
156	      buffer_info.buffer_size = CONFIG_AUDIO_BUFFER_NUMBYTES;
157	    }
158	
159	  if (buffer_info.nbuffers == 0 ||
160	      buffer_info.nbuffers > AUDIO_CAPTURE_MAX_BUFFERS)
161	    {
162	      ret = -E2BIG;
163	      goto fail;
164	    }
165	
166	  snprintf(g_audio_mqname, sizeof(g_audio_mqname), "/audio_event_%ld",
167	           (long)getpid());
168	  memset(&attributes, 0, sizeof(attributes));
169	  attributes.mq_maxmsg = buffer_info.nbuffers + 4;
170	  attributes.mq_msgsize = sizeof(struct audio_msg_s);
171	  g_audio_mq = mq_open(g_audio_mqname, O_RDWR | O_CREAT, 0644, &attributes);
172	  if (g_audio_mq == (mqd_t)-1)
173	    {
174	      ret = -errno;
175	      goto fail;
176	    }
177	
178	  if (ioctl(g_audio_fd, AUDIOIOC_REGISTERMQ,
179	            (unsigned long)g_audio_mq) < 0)
180	    {
181	      ret = -errno;
182	      goto fail;
183	    }
184	
185	  for (i = 0; i < buffer_info.nbuffers; i++)
186	    {
187	      struct audio_buf_desc_s descriptor;
188	
189	      memset(&descriptor, 0, sizeof(descriptor));
190	#ifdef CONFIG_AUDIO_MULTI_SESSION
191	      descriptor.session = g_audio_session;
192	#endif
193	      descriptor.numbytes = buffer_info.buffer_size;
194	      descriptor.u.pbuffer = &g_audio_buffers[i];
195	      if (ioctl(g_audio_fd, AUDIOIOC_ALLOCBUFFER,
196	                (unsigned long)(uintptr_t)&descriptor) != sizeof(descriptor))
197	        {
198	          ret = -ENOMEM;
199	          goto fail;
200	        }
201	
202	      g_audio_buffer_count++;
203	      ret = enqueue_buffer(g_audio_buffers[i]);
204	      if (ret < 0)
205	        {
206	          goto fail;
207	        }
208	    }
209	
210	#ifdef CONFIG_AUDIO_MULTI_SESSION
211	  ret = ioctl(g_audio_fd, AUDIOIOC_START,
212	              (unsigned long)(uintptr_t)g_audio_session);
213	#else
214	  ret = ioctl(g_audio_fd, AUDIOIOC_START, 0);
215	#endif
216	  if (ret < 0)
217	    {
218	      ret = -errno;
219	      goto fail;
220	    }
221	
222	  g_audio_started = true;
223	  printf("[audio] capturing %s at %d Hz, mono, 16-bit\n", device_path,
224	         AUDIO_EVENT_SAMPLE_RATE);
225	  return 0;
226	
227	fail:
228	  audio_capture_deinit();
229	  return ret;
230	}
231	
232	ssize_t audio_capture_read(int16_t *samples, size_t sample_count)
233	{
234	  size_t copied = 0;
235	
236	  if (g_audio_fd < 0 || !g_audio_started || samples == NULL ||
237	      sample_count == 0)
238	    {
239	      return -EINVAL;
240	    }
241	
242	  while (copied < sample_count)
243	    {
244	      size_t available;
245	      size_t take;
246	
247	      if (g_current_buffer == NULL ||
248	          g_current_offset >= g_current_buffer->nbytes)
249	        {
250	          int ret;
251	          if (g_current_buffer != NULL)
252	            {
253	              ret = enqueue_buffer(g_current_buffer);
254	              g_current_buffer = NULL;
255	              if (ret < 0)
256	                {
257	                  return copied > 0 ? (ssize_t)copied : ret;
258	                }
259	            }
260	
261	          ret = wait_for_buffer();
262	          if (ret < 0)
263	            {
264	              return copied > 0 ? (ssize_t)copied : ret;
265	            }
266	        }
267	
268	      available = (g_current_buffer->nbytes - g_current_offset) /
269	                  sizeof(int16_t);
270	      take = sample_count - copied;
271	      if (take > available)
272	        {
273	          take = available;
274	        }
275	
276	      memcpy(samples + copied,
277	             g_current_buffer->samp + g_current_offset,
278	             take * sizeof(int16_t));
279	      copied += take;
280	      g_current_offset += take * sizeof(int16_t);
281	    }
282	
283	  return copied;
284	}
285	
286	void audio_capture_deinit(void)
287	{
288	  unsigned int i;
289	
290	  if (g_audio_fd >= 0 && g_audio_started)
291	    {
292	#ifdef CONFIG_AUDIO_MULTI_SESSION
293	      ioctl(g_audio_fd, AUDIOIOC_STOP,
294	            (unsigned long)(uintptr_t)g_audio_session);
295	#else
296	      ioctl(g_audio_fd, AUDIOIOC_STOP, 0);
297	#endif
298	    }
299	
300	  g_audio_started = false;
301	  g_current_buffer = NULL;
302	  g_current_offset = 0;
303	
304	  if (g_audio_fd >= 0 && g_audio_mq != (mqd_t)-1)
305	    {
306	      ioctl(g_audio_fd, AUDIOIOC_UNREGISTERMQ,
307	            (unsigned long)g_audio_mq);
308	    }
309	
310	  for (i = 0; i < g_audio_buffer_count; i++)
311	    {
312	      struct audio_buf_desc_s descriptor;
313	      if (g_audio_buffers[i] == NULL)
314	        {
315	          continue;
316	        }
317	
318	      memset(&descriptor, 0, sizeof(descriptor));
319	#ifdef CONFIG_AUDIO_MULTI_SESSION
320	      descriptor.session = g_audio_session;
321	#endif
322	      descriptor.u.buffer = g_audio_buffers[i];
323	      ioctl(g_audio_fd, AUDIOIOC_FREEBUFFER,
324	            (unsigned long)(uintptr_t)&descriptor);
325	      g_audio_buffers[i] = NULL;
326	    }
327	
328	  g_audio_buffer_count = 0;
329	  if (g_audio_fd >= 0)
330	    {
331	#ifdef CONFIG_AUDIO_MULTI_SESSION
332	      ioctl(g_audio_fd, AUDIOIOC_RELEASE,
333	            (unsigned long)(uintptr_t)g_audio_session);
334	#else
335	      ioctl(g_audio_fd, AUDIOIOC_RELEASE, 0);
336	#endif
337	      close(g_audio_fd);
338	      g_audio_fd = -1;
339	    }
340	
341	  if (g_audio_mq != (mqd_t)-1)
342	    {
343	      mq_close(g_audio_mq);
344	      mq_unlink(g_audio_mqname);
345	      g_audio_mq = (mqd_t)-1;
346	    }
347	}
