1	/*
2	 * TensorFlow-compatible 49 x 40 log-mel frontend.
3	 */
4	
5	#include <errno.h>
6	#include <math.h>
7	#include <stdbool.h>
8	#include <stdint.h>
9	#include <stdio.h>
10	#include <string.h>
11	
12	#include <tools/kiss_fftr.h>
13	
14	#include "audio_event_config.h"
15	#include "dsp/feature_extract.h"
16	
17	#define MEL_LOWER_HZ        125.0f
18	#define MEL_UPPER_HZ       7500.0f
19	#define LOG_EPSILON           1.0e-6f
20	#define FEATURE_OFFSET       12.0f
21	#define FEATURE_SCALE         1.625f
22	#define FEATURE_MIN           0.0f
23	#define FEATURE_MAX          26.0f
24	#define FFT_STATE_BYTES    8192
25	#define PI_F                   3.14159265358979323846f
26	
27	static uint8_t g_fft_state[FFT_STATE_BYTES] __attribute__((aligned(16)));
28	static kiss_fftr_cfg g_fft;
29	static float g_hann[AUDIO_EVENT_WINDOW_SAMPLES];
30	static float g_fft_input[AUDIO_EVENT_FFT_SIZE];
31	static kiss_fft_cpx g_fft_output[AUDIO_EVENT_FFT_SIZE / 2 + 1];
32	static float g_bin_mel[AUDIO_EVENT_FFT_SIZE / 2 + 1];
33	static float g_band_edge_mel[AUDIO_EVENT_FEATURE_BINS + 2];
34	
35	static float hertz_to_mel(float hertz)
36	{
37	  return 1127.0f * logf(1.0f + hertz / 700.0f);
38	}
39	
40	int feature_extract_init(void)
41	{
42	  size_t fft_state_size = sizeof(g_fft_state);
43	  float lower_mel = hertz_to_mel(MEL_LOWER_HZ);
44	  float upper_mel = hertz_to_mel(MEL_UPPER_HZ);
45	  size_t i;
46	
47	  g_fft = kiss_fftr_alloc(AUDIO_EVENT_FFT_SIZE, 0, g_fft_state,
48	                          &fft_state_size);
49	  if (g_fft == NULL)
50	    {
51	      fprintf(stderr, "[feature] FFT state needs %zu bytes, have %zu\n",
52	              fft_state_size, sizeof(g_fft_state));
53	      return -ENOMEM;
54	    }
55	
56	  /* tf.signal.hann_window() defaults to a periodic window. */
57	
58	  for (i = 0; i < AUDIO_EVENT_WINDOW_SAMPLES; i++)
59	    {
60	      g_hann[i] = 0.5f -
61	                  0.5f * cosf(2.0f * PI_F * (float)i /
62	                              (float)AUDIO_EVENT_WINDOW_SAMPLES);
63	    }
64	
65	  for (i = 0; i <= AUDIO_EVENT_FFT_SIZE / 2; i++)
66	    {
67	      float hertz = (float)i * AUDIO_EVENT_SAMPLE_RATE /
68	                    AUDIO_EVENT_FFT_SIZE;
69	      g_bin_mel[i] = hertz_to_mel(hertz);
70	    }
71	
72	  for (i = 0; i < AUDIO_EVENT_FEATURE_BINS + 2; i++)
73	    {
74	      g_band_edge_mel[i] =
75	          lower_mel + (upper_mel - lower_mel) * (float)i /
76	                      (AUDIO_EVENT_FEATURE_BINS + 1);
77	    }
78	
79	  printf("[feature] log-mel ready: frames=%d bins=%d fft=%d\n",
80	         AUDIO_EVENT_FEATURE_FRAMES, AUDIO_EVENT_FEATURE_BINS,
81	         AUDIO_EVENT_FFT_SIZE);
82	  return 0;
83	}
84	
85	void feature_extract_deinit(void)
86	{
87	  g_fft = NULL;
88	}
89	
90	int feature_extract_compute(const int16_t *samples, size_t sample_count,
91	                            float *features, size_t feature_count)
92	{
93	  size_t frame;
94	
95	  if (g_fft == NULL || samples == NULL || features == NULL ||
96	      sample_count != AUDIO_EVENT_CLIP_SAMPLES ||
97	      feature_count != AUDIO_EVENT_FEATURE_SIZE)
98	    {
99	      return -EINVAL;
100	    }
101	
102	  for (frame = 0; frame < AUDIO_EVENT_FEATURE_FRAMES; frame++)
103	    {
104	      size_t frame_offset = frame * AUDIO_EVENT_WINDOW_STEP_SAMPLES;
105	      size_t i;
106	      int band;
107	
108	      memset(g_fft_input, 0, sizeof(g_fft_input));
109	      for (i = 0; i < AUDIO_EVENT_WINDOW_SAMPLES; i++)
110	        {
111	          float audio = samples[frame_offset + i] / 32768.0f;
112	          g_fft_input[i] = audio * g_hann[i];
113	        }
114	
115	      kiss_fftr(g_fft, g_fft_input, g_fft_output);
116	
117	      for (band = 0; band < AUDIO_EVENT_FEATURE_BINS; band++)
118	        {
119	          float lower = g_band_edge_mel[band];
120	          float center = g_band_edge_mel[band + 1];
121	          float upper = g_band_edge_mel[band + 2];
122	          float mel_energy = 0.0f;
123	          size_t bin;
124	
125	          /* TensorFlow explicitly zeros the DC row of the Mel matrix. */
126	
127	          for (bin = 1; bin <= AUDIO_EVENT_FFT_SIZE / 2; bin++)
128	            {
129	              float mel = g_bin_mel[bin];
130	              float weight;
131	
132	              if (mel <= lower || mel >= upper)
133	                {
134	                  continue;
135	                }
136	
137	              if (mel <= center)
138	                {
139	                  weight = (mel - lower) / (center - lower);
140	                }
141	              else
142	                {
143	                  weight = (upper - mel) / (upper - center);
144	                }
145	
146	              if (weight > 0.0f)
147	                {
148	                  float real = g_fft_output[bin].r;
149	                  float imag = g_fft_output[bin].i;
150	                  float magnitude = sqrtf(real * real + imag * imag);
151	                  mel_energy += magnitude * weight;
152	                }
153	            }
154	
155	          float value = (logf(mel_energy + LOG_EPSILON) + FEATURE_OFFSET) *
156	                        FEATURE_SCALE;
157	          if (value < FEATURE_MIN)
158	            {
159	              value = FEATURE_MIN;
160	            }
161	          else if (value > FEATURE_MAX)
162	            {
163	              value = FEATURE_MAX;
164	            }
165	
166	          features[frame * AUDIO_EVENT_FEATURE_BINS + band] = value;
167	        }
168	    }
169	
170	  return 0;
171	}
