1	/*
2	 * Probability thresholding, consecutive confirmation and cooldown.
3	 */
4	
5	#include <nuttx/config.h>
6	
7	#include <errno.h>
8	#include <stddef.h>
9	
10	#include "audio_event_config.h"
11	#include "detector/event_detector.h"
12	
13	static int g_candidate = -1;
14	static int g_hits;
15	static uint64_t g_cooldown_until_ms;
16	
17	void event_detector_init(void)
18	{
19	  g_candidate = -1;
20	  g_hits = 0;
21	  g_cooldown_until_ms = 0;
22	}
23	
24	int event_detector_update(const float *probabilities, size_t class_count,
25	                          uint64_t timestamp_ms,
26	                          struct event_detection_s *detection)
27	{
28	  float thresholds[2] =
29	    {
30	      CONFIG_EXAMPLES_AUDIO_EVENT_KNOCK_THRESHOLD / 1000.0f,
31	      CONFIG_EXAMPLES_AUDIO_EVENT_COUGH_THRESHOLD / 1000.0f
32	    };
33	  int best = 0;
34	  size_t i;
35	
36	  if (probabilities == NULL || detection == NULL ||
37	      class_count != AUDIO_EVENT_CLASS_COUNT)
38	    {
39	      return -EINVAL;
40	    }
41	
42	  detection->fired = false;
43	  detection->class_id = -1;
44	  detection->confidence = 0.0f;
45	
46	  for (i = 1; i < class_count; i++)
47	    {
48	      if (probabilities[i] > probabilities[best])
49	        {
50	          best = i;
51	        }
52	    }
53	
54	  if (timestamp_ms < g_cooldown_until_ms ||
55	      best > AUDIO_EVENT_CLASS_COUGH || probabilities[best] < thresholds[best])
56	    {
57	      g_candidate = -1;
58	      g_hits = 0;
59	      return 0;
60	    }
61	
62	  if (best == g_candidate)
63	    {
64	      g_hits++;
65	    }
66	  else
67	    {
68	      g_candidate = best;
69	      g_hits = 1;
70	    }
71	
72	  if (g_hits >= CONFIG_EXAMPLES_AUDIO_EVENT_CONSECUTIVE_HITS)
73	    {
74	      detection->fired = true;
75	      detection->class_id = best;
76	      detection->confidence = probabilities[best];
77	      g_cooldown_until_ms = timestamp_ms +
78	                            CONFIG_EXAMPLES_AUDIO_EVENT_COOLDOWN_MS;
79	      g_candidate = -1;
80	      g_hits = 0;
81	    }
82	
83	  return 0;
84	}
