1	/*
2	 * PCM/WAV file input for deterministic simulator tests.
3	 */
4	
5	#include <errno.h>
6	#include <fcntl.h>
7	#include <stdbool.h>
8	#include <stdint.h>
9	#include <stdio.h>
10	#include <string.h>
11	#include <unistd.h>
12	
13	#include "audio/audio_file.h"
14	#include "audio_event_config.h"
15	
16	#define FILE_READ_MAX_SAMPLES 512
17	
18	static uint16_t read_le16(const uint8_t *value)
19	{
20	  return (uint16_t)value[0] | ((uint16_t)value[1] << 8);
21	}
22	
23	static uint32_t read_le32(const uint8_t *value)
24	{
25	  return (uint32_t)value[0] | ((uint32_t)value[1] << 8) |
26	         ((uint32_t)value[2] << 16) | ((uint32_t)value[3] << 24);
27	}
28	
29	static int read_exact(int fd, void *buffer, size_t size)
30	{
31	  uint8_t *cursor = buffer;
32	
33	  while (size > 0)
34	    {
35	      ssize_t count = read(fd, cursor, size);
36	      if (count == 0)
37	        {
38	          return -ENODATA;
39	        }
40	
41	      if (count < 0)
42	        {
43	          if (errno == EINTR)
44	            {
45	              continue;
46	            }
47	
48	          return -errno;
49	        }
50	
51	      cursor += count;
52	      size -= count;
53	    }
54	
55	  return 0;
56	}
57	
58	static bool has_suffix(const char *path, const char *suffix)
59	{
60	  size_t path_length = strlen(path);
61	  size_t suffix_length = strlen(suffix);
62	
63	  return path_length >= suffix_length &&
64	         strcmp(path + path_length - suffix_length, suffix) == 0;
65	}
66	
67	static int parse_wav(struct audio_file_s *source)
68	{
69	  uint8_t header[12];
70	  bool format_found = false;
71	
72	  int ret = read_exact(source->fd, header, sizeof(header));
73	  if (ret < 0 || memcmp(header, "RIFF", 4) != 0 ||
74	      memcmp(header + 8, "WAVE", 4) != 0)
75	    {
76	      return -EINVAL;
77	    }
78	
79	  for (;;)
80	    {
81	      uint8_t chunk[8];
82	      uint32_t chunk_size;
83	
84	      ret = read_exact(source->fd, chunk, sizeof(chunk));
85	      if (ret < 0)
86	        {
87	          return ret;
88	        }
89	
90	      chunk_size = read_le32(chunk + 4);
91	      if (memcmp(chunk, "fmt ", 4) == 0)
92	        {
93	          uint8_t format[16];
94	          if (chunk_size < sizeof(format) ||
95	              read_exact(source->fd, format, sizeof(format)) < 0)
96	            {
97	              return -EINVAL;
98	            }
99	
100	          if (read_le16(format) != 1 || read_le16(format + 2) != 1 ||
101	              read_le32(format + 4) != AUDIO_EVENT_SAMPLE_RATE ||
102	              read_le16(format + 14) != 16)
103	            {
104	              fprintf(stderr,
105	                      "[file] WAV must be PCM, 16 kHz, mono, 16-bit\n");
106	              return -ENOTSUP;
107	            }
108	
109	          if (chunk_size > sizeof(format) &&
110	              lseek(source->fd, chunk_size - sizeof(format), SEEK_CUR) < 0)
111	            {
112	              return -errno;
113	            }
114	
115	          format_found = true;
116	        }
117	      else if (memcmp(chunk, "data", 4) == 0)
118	        {
119	          if (!format_found || (chunk_size & 1) != 0)
120	            {
121	              return -EINVAL;
122	            }
123	
124	          source->data_offset = lseek(source->fd, 0, SEEK_CUR);
125	          source->data_size = chunk_size;
126	          return source->data_offset < 0 ? -errno : 0;
127	        }
128	      else if (lseek(source->fd, chunk_size, SEEK_CUR) < 0)
129	        {
130	          return -errno;
131	        }
132	
133	      if ((chunk_size & 1) != 0 && lseek(source->fd, 1, SEEK_CUR) < 0)
134	        {
135	          return -errno;
136	        }
137	    }
138	}
139	
140	int audio_file_open(struct audio_file_s *source, const char *path,
141	                    unsigned int repeat_count)
142	{
143	  off_t end;
144	  int ret;
145	
146	  if (source == NULL || path == NULL || repeat_count == 0)
147	    {
148	      return -EINVAL;
149	    }
150	
151	  memset(source, 0, sizeof(*source));
152	  source->fd = open(path, O_RDONLY);
153	  if (source->fd < 0)
154	    {
155	      return -errno;
156	    }
157	
158	  source->repeats_left = repeat_count;
159	  if (has_suffix(path, ".wav") || has_suffix(path, ".WAV"))
160	    {
161	      ret = parse_wav(source);
162	      if (ret < 0)
163	        {
164	          audio_file_close(source);
165	          return ret;
166	        }
167	    }
168	  else
169	    {
170	      end = lseek(source->fd, 0, SEEK_END);
171	      if (end < 0 || lseek(source->fd, 0, SEEK_SET) < 0)
172	        {
173	          ret = -errno;
174	          audio_file_close(source);
175	          return ret;
176	        }
177	
178	      source->data_offset = 0;
179	      source->data_size = end;
180	      if ((source->data_size & 1) != 0)
181	        {
182	          audio_file_close(source);
183	          return -EINVAL;
184	        }
185	    }
186	
187	  source->data_read = 0;
188	  printf("[file] opened %s, samples=%zu repeat=%u\n", path,
189	         source->data_size / sizeof(int16_t), repeat_count);
190	  return 0;
191	}
192	
193	ssize_t audio_file_read(struct audio_file_s *source, int16_t *samples,
194	                        size_t sample_count)
195	{
196	  uint8_t bytes[FILE_READ_MAX_SAMPLES * sizeof(int16_t)];
197	  size_t wanted;
198	  size_t i;
199	
200	  if (source == NULL || source->fd < 0 || samples == NULL ||
201	      sample_count == 0 || sample_count > FILE_READ_MAX_SAMPLES)
202	    {
203	      return -EINVAL;
204	    }
205	
206	  if (source->data_read == source->data_size)
207	    {
208	      if (source->repeats_left <= 1)
209	        {
210	          return 0;
211	        }
212	
213	      source->repeats_left--;
214	      source->data_read = 0;
215	      if (lseek(source->fd, source->data_offset, SEEK_SET) < 0)
216	        {
217	          return -errno;
218	        }
219	    }
220	
221	  wanted = sample_count * sizeof(int16_t);
222	  if (wanted > source->data_size - source->data_read)
223	    {
224	      wanted = source->data_size - source->data_read;
225	    }
226	
227	  if (read_exact(source->fd, bytes, wanted) < 0)
228	    {
229	      return -EIO;
230	    }
231	
232	  source->data_read += wanted;
233	  for (i = 0; i < wanted / sizeof(int16_t); i++)
234	    {
235	      samples[i] = (int16_t)read_le16(&bytes[i * sizeof(int16_t)]);
236	    }
237	
238	  return wanted / sizeof(int16_t);
239	}
240	
241	void audio_file_close(struct audio_file_s *source)
242	{
243	  if (source != NULL && source->fd >= 0)
244	    {
245	      close(source->fd);
246	      source->fd = -1;
247	    }
248	}
